// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;
import "@openzeppelin-4/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin-4/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import "@openzeppelin-4/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin-4/contracts/access/Ownable.sol";
import "./interfaces/IBeefySwapperV2.sol";
import "./interfaces/IBoostHubStakingV1.sol";
import "./interfaces/IStrategyBoostHubV1.sol";
import "./FXNPositionInterfacesV43.sol";
interface IVaultAPYUnifiedV43 { function updateAPY() external; }
/// @notice Independent positions and profit locks, one strategy custody boundary.
contract StrategyDualFXNUnifiedV43 is ReentrancyGuard, Ownable, IStrategyBoostHubV1 {
    using SafeERC20 for IERC20;
    error InvalidDependency();error VaultOnly();error InvalidTargets();error GuardUnavailable();error InvalidReward();error InvalidExit();error InvalidMigration();error InvalidRecipient();error SwapOutputZero();
    uint256 public constant WAD=1e18;
    uint256 public constant MAX_BPS=10_000;
    uint256 public constant PEG_MIN_WAD=969e15;
    uint256 public constant LOCK_DURATION=1 days;
    uint16 public constant BOOST_FEE_BPS=300;
    uint16 public constant CONVEX_FEE_BPS=1300;
    uint16 public constant CALL_SHARE_BPS=1000;
    uint16 public constant CURVE_LP_SLIPPAGE_BPS=75;
    uint256 public constant PID=8;
    address public immutable override vault;
    address public immutable override want;
    address public immutable fxn;
    address public immutable swapper;
    address public immutable adminFeeReceiverAddress;
    IBoostHubStakingV1 public immutable staking;
    IFXCurvePoolV42 public immutable curvePool;
    IFXStakingProxyV42 public immutable convexVault;
    IFXGaugeV42 public immutable gauge;
    IFXRewardsV42 public immutable rewardPool;
    ICurveLiquidityBoundsFXNV49 public curveLiquidityGuard;
    uint16 public boostCapBps=2000;
    uint16 public convexCapBps=8000;
    struct ProfitLock { uint256 amount; uint256 timestamp; }
    ProfitLock[2] private positionLocks;
    // The former Convex child held any withdrawal overshoot separately.
    uint256 public convexIdle;
    uint256 public totalLocked;
    uint256 public lastHarvest;
    // Preserve attribution of deferred non-want rewards even after registry changes.
    mapping(address=>uint8) private rewardLane;
    event AllocationCapsUpdated(uint16 boostCapBps,uint16 convexCapBps);
    event Allocation(uint8 indexed position,uint256 deposited);
    event Deallocation(uint8 indexed position,uint256 withdrawn);
    event ManualMigration(uint8 indexed fromStrategyIndex,uint256 sourceUnits,uint256 transferredWant);
    event MasterHarvest(address indexed caller);
    event PositionHarvest(uint8 indexed position,uint256 wantHarvested);
    event ChargedFees(uint8 indexed position,uint256 callFees,uint256 adminFees);
    event RewardSwapDeferred(address indexed token,uint256 amount);
    event CurveLiquidityGuardUpdated(address indexed previousGuard,address indexed newGuard);
    event EmergencyCurveExit(uint256 lpRedeemed,uint256 underlyingReceived);
    constructor(address vault_,address want_,address fxn_,address swapper_,address staking_,address booster_,address curvePool_,address guard_,address feeReceiver_) {
        if(block.chainid!=1 || vault_==address(0) || want_.code.length==0 || fxn_.code.length==0 ||
            swapper_.code.length==0 || staking_.code.length==0 || booster_.code.length==0 ||
            curvePool_.code.length==0 || feeReceiver_==address(0) || IERC20Metadata(want_).decimals()!=18) revert InvalidDependency();
        vault=vault_;want=want_;fxn=fxn_;swapper=swapper_;adminFeeReceiverAddress=feeReceiver_;
        staking=IBoostHubStakingV1(staking_);
        if(staking.lp_token()!=want_) revert InvalidDependency();
        curvePool=IFXCurvePoolV42(curvePool_);
        if(curvePool.coins(0)!=fxn_ || curvePool.coins(1)!=want_) revert InvalidDependency();
        IFXBoosterV42 booster=IFXBoosterV42(booster_);
        (,,address lp,address rewards,uint8 active)=IFXPoolRegistryV42(booster.poolRegistry()).poolInfo(PID);
        if(active==0 || lp!=curvePool_ || rewards.code.length==0) revert InvalidDependency();
        IFXStakingProxyV42 proxy=IFXStakingProxyV42(booster.createVault(PID));
        if(address(proxy)==address(0) || proxy.owner()!=address(this) || proxy.pid()!=PID ||
            proxy.stakingToken()!=curvePool_ || proxy.gaugeAddress().code.length==0) revert InvalidDependency();
        convexVault=proxy;gauge=IFXGaugeV42(proxy.gaugeAddress());rewardPool=IFXRewardsV42(rewards);
        IERC20(want_).forceApprove(staking_,type(uint256).max);
        IERC20(want_).forceApprove(curvePool_,type(uint256).max);
        IERC20(curvePool_).forceApprove(address(proxy),type(uint256).max);
        _setGuard(guard_);
        _bindRewardSets(_boostRewards(),_convexRewards());
    }
    function _setGuard(address guard) private {
        if(guard!=address(0) && guard.code.length==0) revert InvalidDependency();
        emit CurveLiquidityGuardUpdated(address(curveLiquidityGuard),guard);
        curveLiquidityGuard=ICurveLiquidityBoundsFXNV49(guard);
    }
    function setConvexCurveLiquidityGuard(address guard) external onlyOwner {_setGuard(guard);}
    function _guard() private view returns(ICurveLiquidityBoundsFXNV49 g) {g=curveLiquidityGuard;if(address(g).code.length==0)revert GuardUnavailable();}
    function allocationTargets() external view returns(uint256,uint256){return(boostCapBps,convexCapBps);}
    function setAllocationTargets(uint16 b,uint16 c) external onlyOwner {if(uint256(b)+c!=MAX_BPS)revert InvalidTargets();boostCapBps=b;convexCapBps=c;emit AllocationCapsUpdated(b,c);}
    function sdFxnToFxnWad() public view returns(uint256) {try IBeefySwapperV2(swapper).getAmountOut(want,fxn,WAD) returns(uint256 a){return a;} catch{return 0;}}
    function convexEligible() public view returns(bool){return address(curveLiquidityGuard).code.length!=0 && sdFxnToFxnWad()>PEG_MIN_WAD;}
    function _want() private view returns(uint256){return IERC20(want).balanceOf(address(this));}
    function _masterIdle() private view returns(uint256){return _want()-convexIdle;}
    function _decay(uint256 amount,uint256 time) private view returns(uint256) {uint256 age=block.timestamp-time;return age>=LOCK_DURATION?0:amount*(LOCK_DURATION-age)/LOCK_DURATION;}
    function lockedProfit() public view returns(uint256){return _decay(totalLocked,lastHarvest);}
    function positionLockedProfit(uint8 position) public view returns(uint256){ProfitLock storage l=positionLocks[position];return _decay(l.amount,l.timestamp);}
    function _lockPosition(uint8 position,uint256 gain) private {positionLocks[position]=ProfitLock(positionLockedProfit(position)+gain,block.timestamp);}
    function lpBalance() public view returns(uint256){return gauge.balanceOf(address(convexVault))+IERC20(address(curvePool)).balanceOf(address(this));}
    function _grossPositions() private view returns(uint256 b,uint256 c){b=staking.balanceOf(address(this));uint256 lp=lpBalance();c=convexIdle+(lp==0?0:curvePool.calc_withdraw_one_coin(lp,1));}
    function _netPositions() private view returns(uint256 b,uint256 c){(b,c)=_grossPositions();b-=positionLockedProfit(0);c-=positionLockedProfit(1);}
    function childBalances() external view returns(uint256,uint256){return _netPositions();}
    function balanceOf() public view override returns(uint256){(uint256 b,uint256 c)=_netPositions();uint256 sum=_masterIdle()+b+c;uint256 locked=lockedProfit();return sum>locked?sum-locked:0;}
    function _targets(uint256 gross) private view returns(uint256 b,uint256 c){b=gross*boostCapBps/MAX_BPS;c=gross-b;}
    function _convexDeposit(uint256 amount) private {
        uint256[2] memory amounts;amounts[1]=amount;
        (,uint256 minLp)=_guard().quoteDeposit(address(curvePool),1,amount,CURVE_LP_SLIPPAGE_BPS);
        if(minLp==0) revert InvalidExit();
        uint256 beforeLp=IERC20(address(curvePool)).balanceOf(address(this));
        curvePool.add_liquidity(amounts,minLp);
        uint256 received=IERC20(address(curvePool)).balanceOf(address(this))-beforeLp;
        if(received==0) revert InvalidExit();convexVault.deposit(received);
    }
    function _invest(uint8 position,uint256 amount) private {if(amount==0)return;if(position==0)staking.deposit(amount,address(this));else {uint256 invested=amount+convexIdle;convexIdle=0;_convexDeposit(invested);}emit Allocation(position,amount);}
    function _allocateAvailable() private {
        uint256 idle=_masterIdle();uint256 locked=lockedProfit();uint256 free=idle>locked?idle-locked:0;if(free==0)return;
        (uint256 b,uint256 c)=_grossPositions();(uint256 bt,uint256 ct)=_targets(idle+IERC20(want).balanceOf(vault)+b+c);
        uint256 bd=bt>b?bt-b:0;uint256 cd=ct>c?ct-c:0;if(cd!=0 && !convexEligible())cd=0;
        if(cd>bd){uint256 x=free<cd?free:cd;_invest(1,x);free-=x;_invest(0,free<bd?free:bd);}
        else{uint256 x=free<bd?free:bd;_invest(0,x);free-=x;_invest(1,free<cd?free:cd);}
    }
    function deposit() external override nonReentrant {_allocateAvailable();}
    function rebalanceAllocations() external nonReentrant {_allocateAvailable();}
    function _redeemLp(uint256 units,bool emergency) private returns(uint256 received){
        uint256 idleLp=IERC20(address(curvePool)).balanceOf(address(this));if(units>idleLp)convexVault.withdraw(units-idleLp);
        uint256 minOut;if(!emergency){(,minOut)=_guard().quoteWithdraw(address(curvePool),1,units,CURVE_LP_SLIPPAGE_BPS);if(minOut==0)revert InvalidExit();}
        uint256 beforeWant=_want();curvePool.remove_liquidity_one_coin(units,1,minOut);received=_want()-beforeWant;
        if(emergency)emit EmergencyCurveExit(units,received);
    }
    function _convexWithdraw(uint256 amount,bool emergency) private {
        for(uint256 n;n<3 && convexIdle<amount;++n){
            uint256 lp=lpBalance();if(lp==0)revert InvalidExit();uint256 estimate;
            if(emergency)estimate=curvePool.calc_withdraw_one_coin(lp,1);else (estimate,)=_guard().quoteWithdraw(address(curvePool),1,lp,CURVE_LP_SLIPPAGE_BPS);
            if(estimate==0)revert InvalidExit();uint256 need=amount-convexIdle;
            uint256 target=(lp*need+estimate-1)/estimate;target+=target/100+1;if(target>lp)target=lp;convexIdle+=_redeemLp(target,emergency);
        }
        if(convexIdle<amount)revert InvalidExit();convexIdle-=amount;
    }
    function _take(uint8 position,uint256 need,bool emergency,uint256 available) private returns(uint256 requested){
        requested=need<available?need:available;if(requested==0)return 0;uint256 beforeFree=_masterIdle();
        if(position==0)staking.withdraw(requested);else _convexWithdraw(requested,emergency);
        if(_masterIdle()-beforeFree<requested)revert InvalidExit();emit Deallocation(position,requested);
    }
    function withdraw(uint256 amount) external override nonReentrant{_withdrawForVault(amount,false);}
    function emergencyWithdraw(uint256 amount) external nonReentrant{_withdrawForVault(amount,true);}
    function _withdrawForVault(uint256 amount,bool emergency) private {
        if(msg.sender!=vault)revert VaultOnly();(uint256 b,uint256 c)=_netPositions();uint256 idle=_masterIdle();uint256 locked=lockedProfit();
        uint256 sum=idle+b+c;if(amount>(sum>locked?sum-locked:0))revert InvalidExit();if(amount==0)return;
        uint256 free=idle>locked?idle-locked:0;uint256 need=amount>free?amount-free:0;
        if(need!=0){
            uint256 bg=b+positionLockedProfit(0);uint256 cg=c+positionLockedProfit(1);
            uint256 gross=idle+IERC20(want).balanceOf(vault)+bg+cg;(uint256 bt,uint256 ct)=_targets(gross>amount?gross-amount:0);
            uint256 be=bg>bt?bg-bt:0;uint256 ce=cg>ct?cg-ct:0;bool convexFirst=ce>be;
            uint256 got=_take(convexFirst?1:0,need,emergency,convexFirst?c:b);
